package com.centralplay.app.ui;
import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.centralplay.app.R;import com.centralplay.app.data.*;import com.google.android.material.appbar.MaterialToolbar;import com.google.android.material.switchmaterial.SwitchMaterial;import com.google.android.material.textfield.TextInputEditText;
public class SettingsActivity extends AppCompatActivity{private TextInputEditText url,pin;private SwitchMaterial adult;private TextView status;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_settings);MaterialToolbar tb=findViewById(R.id.toolbar);tb.setNavigationOnClickListener(v->finish());url=findViewById(R.id.manifest_url);pin=findViewById(R.id.pin);adult=findViewById(R.id.adult_switch);status=findViewById(R.id.status);url.setText(Prefs.manifestUrl(this));pin.setText(Prefs.pin(this));adult.setChecked(Prefs.adultEnabled(this));findViewById(R.id.save).setOnClickListener(v->save());findViewById(R.id.sync).setOnClickListener(v->sync());findViewById(R.id.clear_cache).setOnClickListener(v->{CatalogRepository.get(this).clearCache();Toast.makeText(this,"Caché borrada",Toast.LENGTH_SHORT).show();});findViewById(R.id.history).setOnClickListener(v->startActivity(new Intent(this,HistoryActivity.class)));findViewById(R.id.downloads).setOnClickListener(v->{try{startActivity(new Intent(android.app.DownloadManager.ACTION_VIEW_DOWNLOADS));}catch(Exception e){Toast.makeText(this,"No se pudo abrir Descargas",Toast.LENGTH_SHORT).show();}});findViewById(R.id.diagnostics).setOnClickListener(v->startActivity(new Intent(this,DiagnosticsActivity.class)));updateStatus();}private void save(){String p=pin.getText()==null?"":pin.getText().toString().trim();if(!p.isEmpty()&&(p.length()<4||p.length()>8)){pin.setError("Usá entre 4 y 8 dígitos");return;}Prefs.setManifestUrl(this,url.getText()==null?"":url.getText().toString());Prefs.setPin(this,p);Prefs.setAdultEnabled(this,adult.isChecked());Toast.makeText(this,"Ajustes guardados",Toast.LENGTH_SHORT).show();sync();}private void sync(){status.setText("Sincronizando…");CatalogRepository.get(this).refreshAsync((c,s,e)->{updateStatus();Toast.makeText(this,e.trim().isEmpty()?"Sincronización correcta":"Sincronización con fallback: "+e,Toast.LENGTH_LONG).show();});}private void updateStatus(){status.setText("Fuente: "+Prefs.syncSource(this)+(Prefs.syncError(this).trim().isEmpty()?"":"\nError: "+Prefs.syncError(this)));}}
